355	// TestOpenDestroyedAccountingUsesChildInitialOnly 核对只取各直接子样创建
356	// 时的初始量：
357	//   - 孙样不重复计入：父样分出 4.000 给子样，子样又把 4.000 全部分给孙样，
358	//     父样销毁 6.000 仍满足 6.000 + 4.000 = 10.000；
359	//   - 子样后来继续分装、转交或销毁不改变父样已分出的量：子样当前只剩
360	//     2.250（自身又分出 1.000）或已全部销毁，父样仍按子样初始量 3.250 核
361	//     对，不能改用子样当前剩余量。
362	func TestOpenDestroyedAccountingUsesChildInitialOnly(t *testing.T) {
363		// 场景一：孙样不重复计入；子样分装用尽（无销毁信息）也合法。
364		grandchild := plainChild("G", "C", 4000, 4000)
365		childExhausted := plainChild("C", "P", 4000, 0)
366		childExhausted.Children = []string{"G"}
367		childExhausted.History = append(childExhausted.History, historyRecord{
368			Kind: "split", Time: splitCheckAt.Add(time.Hour), Holder: "李四", Location: "实验室B",
369		})
370		l1 := &ledger{
371			Samples: map[string]*sampleRecord{
372				"P": destroyedSample("P", 10000, 0, 6000, "C"),
373				"C": childExhausted,
374				"G": grandchild,
375			},
376		}
377		if s, err := Open(writeStructLedger(t, l1)); err != nil {
378			t.Fatalf("孙样不得计入父样销毁核对，6.000+4.000=10.000 应恢复: %v", err)
379		} else {
380			p, _ := s.GetSample("P")
381			if p.Destruction == nil || p.Destruction.Qty != "6.000" {
382				t.Fatalf("父样销毁量恢复错误: %+v", p.Destruction)
383			}
384		}
385	
386		// 场景二：子样自己又分出 1.000，当前只剩 2.250；父样仍按子样初始量
387		// 3.250 核对（6.750 + 3.250 = 10.000）。
388		childSplit := plainChild("S-001-A", "S-001", 3250, 2250)
389		childSplit.Children = []string{"S-001-A-G"}
390		childSplit.History = append(childSplit.History, historyRecord{
391			Kind: "split", Time: splitCheckAt.Add(time.Hour), Holder: "李四", Location: "实验室B",
392		})
393		l2 := &ledger{
394			Samples: map[string]*sampleRecord{
395				"S-001":     destroyedSample("S-001", 10000, 0, 6750, "S-001-A"),
396				"S-001-A":   childSplit,
397				"S-001-A-G": plainChild("S-001-A-G", "S-001-A", 1000, 1000),
398			},
399		}
400		if _, err := Open(writeStructLedger(t, l2)); err != nil {
401			t.Fatalf("必须按子样创建时初始量 3.250 核对，不能用其当前剩余 2.250: %v", err)
402		}
403	
404		// 场景三：子样已独立销毁（销毁量取其当时剩余 2.250），父样核对仍按
405		// 子样初始量 3.250；父子销毁记录恢复后各自独立。
406		childDestroyed := destroyedSampleWithParent("S-001-A", "S-001", 3250, 2250)
407		childDestroyed.Children = []string{"S-001-A-G"}
408		grand := plainChild("S-001-A-G", "S-001-A", 1000, 1000)
409		l3 := &ledger{
410			Samples: map[string]*sampleRecord{
411				"S-001":     destroyedSample("S-001", 10000, 0, 6750, "S-001-A"),
412				"S-001-A":   childDestroyed,
413				"S-001-A-G": grand,
414			},
415		}
416		s3, err := Open(writeStructLedger(t, l3))
417		if err != nil {
418			t.Fatalf("子样后来销毁不改变父样已分出量，文件应正常恢复: %v", err)
419		}
420		parent, _ := s3.GetSample("S-001")
421		child, _ := s3.GetSample("S-001-A")
422		if parent.Destruction == nil || parent.Destruction.Qty != "6.750" {
423			t.Fatalf("父样销毁量应为 6.750: %+v", parent.Destruction)
424		}
425		if child.Destruction == nil || child.Destruction.Qty != "2.250" || child.Remaining != "0.000" {
426			t.Fatalf("子样销毁记录应独立保留为 2.250: %+v", child.Destruction)
427		}
428	}
