1	package custody
2	
3	import (
4		"bytes"
5		"errors"
6		"os"
7		"path/filepath"
8		"reflect"
9		"strings"
10		"testing"
11		"time"
12	)
13	
14	// destroySaveFixture 是“原样已分出过子样、仍有剩余量、没有待确认交接且
15	// 未销毁，当前持有人在记录地点提交的销毁请求本身完全合法”的测试前置状态。
16	type destroySaveFixture struct {
17		dir, path string
18		s         *Store
19		in        DestroyInput
20	
21		// parentID 为待销毁原样；childID 是此前已成功分出、并已独立交接给
22		// 别人在别处持有的原有子样，对原样的失败销毁不得带动它。
23		parentID, childID string
24	
25		// 失败前原样、原有子样的查询视图与磁盘数据内容；任何保存失败
26		// 之后，它们都应保持不变。
27		parentBefore *Sample
28		childBefore  *Sample
29		diskBefore   []byte
30	}
31	
32	// setupDestroyableParent 准备：登记 10.000 毫升原样 → 成功分出 3.250 毫升
33	// 子样（原样剩余 6.750）→ 子样经交接由别人在别处持有。原样未销毁、无
34	// 待确认交接，当前持有人仍在记录地点，销毁时间晚于全部已有历史。
35	func setupDestroyableParent(t *testing.T) *destroySaveFixture {
36		t.Helper()
37		dir := t.TempDir()
38		path := filepath.Join(dir, "data.json")
39	
40		s, err := Open(path)
41		if err != nil {
42			t.Fatalf("open: %v", err)
43		}
44		clock := time.Date(2026, 10, 2, 9, 0, 0, 0, time.UTC)
45		s.now = func() time.Time { return clock }
46	
47		const parentID, childID = "P", "C0"
48		mustRegister(t, s, parentID, "10.000", "张三", "实验室A")
49		if _, err := s.Split(SplitInput{ParentID: parentID, Parts: []SplitPart{
50			{ID: childID, Qty: "3.250"},
51		}}); err != nil {
52			t.Fatalf("前置分装: %v", err)
53		}
54	
55		// 原有子样交接给别人、在别处确认：它有独立于原样的数量、持有人、
56		// 地点和保管历史（分出 → 交出 → 接收）。
57		hAt := clock.Add(time.Hour)
58		rAt := hAt.Add(time.Hour)
59		if _, err := s.Handover(HandoverInput{
60			TransferID: "TR-C0", SampleID: childID,
61			FromHolder: "张三", FromLocation: "实验室A",
62			ToHolder: "李四", ToLocation: "实验室B",
63			HandedOverAt: hAt,
64		}); err != nil {
65			t.Fatalf("前置交接发起: %v", err)
66		}
67		if _, err := s.Confirm(ConfirmInput{"TR-C0", "李四", "实验室B", rAt}); err != nil {
68			t.Fatalf("前置交接确认: %v", err)
69		}
70	
71		// 销毁时间晚于原样与子样的全部已有保管历史，请求本身满足销毁条件。
72		destroyAt := clock.Add(4 * time.Hour)
73	
74		parentBefore, err := s.GetSample(parentID)
75		if err != nil {
76			t.Fatal(err)
77		}
78		childBefore, err := s.GetSample(childID)
79		if err != nil {
80			t.Fatal(err)
81		}
82		disk, err := os.ReadFile(path)
83		if err != nil {
84			t.Fatalf("read persisted data: %v", err)
85		}
86	
87		// 前置条件自检：原样初始 10.000、剩余 6.750、无待确认、未销毁，
88		// 持有人和地点仍是登记记录；原有子样独立持有，数量 3.250。
89		if parentBefore.InitialQty != "10.000" || parentBefore.Remaining != "6.750" ||
90			parentBefore.Holder != "张三" || parentBefore.Location != "实验室A" ||
91			parentBefore.PendingTransfer != nil || parentBefore.Destruction != nil {
92			t.Fatalf("前置原样状态不正确: %+v", parentBefore)
93		}
94		if len(parentBefore.Children) != 1 || parentBefore.Children[0] != childID ||
95			len(parentBefore.History) != 2 {
96			t.Fatalf("前置原样的子样与历史不正确: %+v", parentBefore)
97		}
98		if childBefore.InitialQty != "3.250" || childBefore.Remaining != "3.250" ||
99			childBefore.ParentID != parentID ||
100			childBefore.Holder != "李四" || childBefore.Location != "实验室B" ||
101			len(childBefore.History) != 3 {
102			t.Fatalf("前置原有子样状态不正确: %+v", childBefore)
103		}
104	
105		return &destroySaveFixture{
106			dir: dir, path: path, s: s,
107			parentID: parentID, childID: childID,
108			in: DestroyInput{
109				SampleID: parentID, Operator: "张三", Location: "实验室A",
110				At: destroyAt, Reason: "实验结束按规程销毁",
111			},
112			parentBefore: parentBefore,
113			childBefore:  childBefore,
114			diskBefore:   disk,
115		}
116	}
117	
118	// assertDestroyDidNotTakeEffect 断言一次保存失败的销毁完全没有生效：
119	// 原样逐项保持失败前状态、销毁信息与销毁历史均不存在，原有子样不受带动。
120	func assertDestroyDidNotTakeEffect(t *testing.T, f *destroySaveFixture) {
121		t.Helper()
122	
123		parent, err := f.s.GetSample(f.parentID)
124		if err != nil {
125			t.Fatalf("get parent: %v", err)
126		}
127		if !reflect.DeepEqual(parent, f.parentBefore) {
128			t.Fatalf("保存失败后原样状态被改动:\n before=%+v\n after =%+v",
129				f.parentBefore, parent)
130		}
131		// 关键业务字段再逐项点明：初始量、剩余量、持有人、地点、子样列表。
132		if parent.InitialQty != "10.000" || parent.Remaining != "6.750" {
133			t.Fatalf("原样剩余量不应被提前清零: init=%s remaining=%s",
134				parent.InitialQty, parent.Remaining)
135		}
136		if parent.Holder != "张三" || parent.Location != "实验室A" {
137			t.Fatalf("原样持有人和地点不应变化: %s @ %s", parent.Holder, parent.Location)
138		}
139		if len(parent.Children) != 1 || parent.Children[0] != f.childID {
140			t.Fatalf("原样子样列表不应变化: %v", parent.Children)
141		}
142		if parent.PendingTransfer != nil {
143			t.Fatalf("失败的销毁不得引入待确认交接: %+v", parent.PendingTransfer)
144		}
145		if parent.Destruction != nil {
146			t.Fatalf("失败的销毁不得留下销毁信息（不能让重试被误当成已完成的销毁）: %+v",
147				parent.Destruction)
148		}
149		// 保管历史中不得出现销毁事件，长度与内容都停留在失败前。
150		if len(parent.History) != len(f.parentBefore.History) {
151			t.Fatalf("失败的销毁不得追加历史: before=%d after=%d",
152				len(f.parentBefore.History), len(parent.History))
153		}
154		for _, h := range parent.History {
155			if h.Kind == "destroy" {
156				t.Fatalf("保管历史中不应出现销毁事件: %+v", h)
157			}
158		}
159	
160		child, err := f.s.GetSample(f.childID)
161		if err != nil {
162			t.Fatalf("get existing child: %v", err)
163		}
164		if !reflect.DeepEqual(child, f.childBefore) {
165			t.Fatalf("原有子样不应被原样的失败销毁带动:\n before=%+v\n after =%+v",
166				f.childBefore, child)
167		}
168		if child.InitialQty != "3.250" || child.Remaining != "3.250" ||
169			child.Destruction != nil {
170			t.Fatalf("原有子样的数量与保管记录不应变化: %+v", child)
171		}
172	}
173	
174	// TestDestroySaveFailureIsAtomic 覆盖销毁请求完全符合业务规则、但结果无法
175	// 保存到本地数据文件时的回归：Destroy 必须返回说明保存失败的错误（而不是
176	// 成功结果，也不能归为入参非法、状态冲突或样品不存在），原样不会提前进入
177	// 已销毁状态，磁盘上不留下数量归零、只剩销毁信息或只剩新增历史的部分结果；
178	// 恢复保存后继续用原来打开的数据以同一份销毁信息重试，应恰好销毁当时的
179	// 全部剩余量（6.750 毫升）一次，再次提交仍返回这次成功结果且不追加历史。
180	func TestDestroySaveFailureIsAtomic(t *testing.T) {
181		cases := []struct {
182			name string
183			// wantErrFragment 是对应保存环节的错误文本，用于区分两类失败。
184			wantErrFragment string
185			// inject 制造一次保存失败，返回失败期间原数据所在的可读路径，
186			// 以及恢复函数（幂等，同时注册到 t.Cleanup）。
187			inject func(t *testing.T, dir, path string) (preservedPath string, restore func())
188		}{
189			{
190				name:            "数据目录无法创建临时文件",
191				wantErrFragment: "创建临时数据文件失败",
192				inject: func(t *testing.T, dir, path string) (string, func()) {
193					if err := os.Chmod(dir, 0o555); err != nil {
194						t.Fatalf("chmod dir: %v", err)
195					}
196					restored := false
197					restore := func() {
198						if restored {
199							return
200						}
201						restored = true
202						_ = os.Chmod(dir, 0o755)
203					}
204					t.Cleanup(restore)
205					return path, restore
206				},
207			},
208			{
209				name:            "新数据已写出但无法替换原数据文件",
210				wantErrFragment: "替换本地样品数据文件失败",
211				inject: func(t *testing.T, dir, path string) (string, func()) {
212					// 把原数据文件移开并在同一路径放置一个目录：临时文件可以
213					// 正常写入同目录（新数据已完整写出），但原子 rename 无法
214					// 用文件替换一个目录。
215					aside := path + ".preserved"
216					if err := os.Rename(path, aside); err != nil {
217						t.Fatalf("move data file aside: %v", err)
218					}
219					if err := os.Mkdir(path, 0o755); err != nil {
220						t.Fatalf("place directory at data path: %v", err)
221					}
222					restored := false
223					restore := func() {
224						if restored {
225							return
226						}
227						restored = true
228						if _, err := os.Lstat(path); err == nil {
229							_ = os.RemoveAll(path)
230						}
231						_ = os.Rename(aside, path)
232					}
233					t.Cleanup(restore)
234					return aside, restore
235				},
236			},
237		}
238	
239		for _, tc := range cases {
240			t.Run(tc.name, func(t *testing.T) {
241				f := setupDestroyableParent(t)
242				preservedPath, restore := tc.inject(t, f.dir, f.path)
243	
244				// 操作人、地点、销毁时间和原因本身都满足销毁条件，原样仍有
245				// 6.750 剩余、无待确认、未销毁——销毁本身完全可做，仅保存失败。
246				done, err := f.s.Destroy(f.in)
247				if err == nil {
248					t.Fatalf("保存失败时销毁应返回错误，却得到成功结果: %+v", done)
249				}
250				if done != nil {
251					t.Fatalf("保存失败不应返回表示销毁成功的样品结果: %+v", done)
252				}
253				for _, sentinel := range []error{ErrInvalid, ErrConflict, ErrNotFound} {
254					if errors.Is(err, sentinel) {
255						t.Fatalf("保存错误不应被包装为 %v，否则调用方会误判能否重试，实际错误: %v",
256							sentinel, err)
257					}
258				}
259				if !strings.Contains(err.Error(), tc.wantErrFragment) {
260					t.Fatalf("应返回 %q 对应的保存错误, got %v", tc.wantErrFragment, err)
261				}
262	
263				// 失败后立即从原来打开的数据查询：原样与原有子样停留在提交前。
264				assertDestroyDidNotTakeEffect(t, f)
265	
266				// 保存仍未恢复时再次提交同一请求：必须再次报保存失败，而不是
267				// 被当作“上一次销毁已完成”幂等返回成功结果。
268				done2, err2 := f.s.Destroy(f.in)
269				if err2 == nil || done2 != nil {
270					t.Fatalf("保存未恢复时的重试也必须失败且不返回成功结果: view=%+v err=%v",
271						done2, err2)
272				}
273				for _, sentinel := range []error{ErrInvalid, ErrConflict, ErrNotFound} {
274					if errors.Is(err2, sentinel) {
275						t.Fatalf("保存未恢复时的重试不应被归为业务错误 %v: %v", sentinel, err2)
276					}
277				}
278				if !strings.Contains(err2.Error(), tc.wantErrFragment) {
279					t.Fatalf("重试仍应返回 %q 对应的保存错误, got %v",
280						tc.wantErrFragment, err2)
281				}
282				assertDestroyDidNotTakeEffect(t, f)
283	
284				// 此前保存的数据文件保持原有业务内容：不能留下数量归零、
285				// 只有销毁信息或只有新增历史的部分结果。
286				preserved, err := os.ReadFile(preservedPath)
287				if err != nil {
288					t.Fatalf("读取原数据文件: %v", err)
289				}
290				if !bytes.Equal(preserved, f.diskBefore) {
291					t.Fatalf("保存失败改动了磁盘上的原数据文件")
292				}
293	
294				// 恢复正常文件访问：数据文件回到原路径，内容仍是失败前的状态。
295				restore()
296				disk, err := os.ReadFile(f.path)
297				if err != nil {
298					t.Fatalf("恢复后读取数据文件: %v", err)
299				}
300				if !bytes.Equal(disk, f.diskBefore) {
301					t.Fatalf("恢复后数据文件内容应与失败前一致")
302				}
303	
304				// 继续使用原来打开的数据，重新提交同一份销毁信息：应成功销毁
305				// 当时的全部剩余量 6.750（初始 10.000 − 已分出 3.250）。
306				destroyed, err := f.s.Destroy(f.in)
307				if err != nil {
308					t.Fatalf("恢复后用相同销毁信息重新提交应成功: %v", err)
309				}
310				if destroyed.Remaining != "0.000" {
311					t.Fatalf("成功重试后原样剩余量应为 0.000, got %s", destroyed.Remaining)
312				}
313				if destroyed.InitialQty != "10.000" {
314					t.Fatalf("初始量应保留为 10.000, got %s", destroyed.InitialQty)
315				}
316				if destroyed.Destruction == nil {
317					t.Fatalf("成功重试后应带销毁记录")
318				}
319				d := destroyed.Destruction
320				if d.Qty != "6.750" {
321					t.Fatalf("成功重试记录的销毁量应为当时全部剩余量 6.750, got %s", d.Qty)
322				}
323				if d.Operator != "张三" || d.Location != "实验室A" ||
324					d.Reason != "实验结束按规程销毁" || !d.At.Equal(f.in.At) {
325					t.Fatalf("销毁记录应保留提交的操作人、地点、时间和原因: %+v", d)
326				}
327				if destroyed.Holder != "张三" || destroyed.Location != "实验室A" {
328					t.Fatalf("销毁后持有人和地点保留为销毁前的最后记录: %s @ %s",
329						destroyed.Holder, destroyed.Location)
330				}
331				if len(destroyed.Children) != 1 || destroyed.Children[0] != f.childID {
332					t.Fatalf("销毁应保留子样列表: %v", destroyed.Children)
333				}
334				// 原样只增加一次销毁历史，原有历史原样保留。
335				if len(destroyed.History) != len(f.parentBefore.History)+1 {
336					t.Fatalf("原样历史应只增加一次销毁记录: before=%d after=%d",
337						len(f.parentBefore.History), len(destroyed.History))
338				}
339				if !reflect.DeepEqual(destroyed.History[:len(f.parentBefore.History)],
340					f.parentBefore.History) {
341					t.Fatalf("原样原有保管历史应保持不变: %+v", destroyed.History)
342				}
343				last := destroyed.History[len(destroyed.History)-1]
344				if last.Kind != "destroy" || !last.Time.Equal(f.in.At) ||
345					last.Holder != "张三" || last.Location != "实验室A" ||
346					!strings.Contains(last.Detail, "6.750") ||
347					!strings.Contains(last.Detail, "实验结束按规程销毁") {
348					t.Fatalf("新增历史不是本次销毁记录: %+v", last)
349				}
350	
351				// 已分出的子样仍保持自己的 3.250 毫升与保管记录，不被原样的
352				// 失败与随后的成功销毁带动。
353				child, err := f.s.GetSample(f.childID)
354				if err != nil {
355					t.Fatal(err)
356				}
357				if !reflect.DeepEqual(child, f.childBefore) {
358					t.Fatalf("原有子样不应被原样销毁带动:\n before=%+v\n after =%+v",
359						f.childBefore, child)
360				}
361	
362				// 再次提交相同信息：返回这次成功保存的结果，不再追加历史。
363				again, err := f.s.Destroy(DestroyInput{
364					SampleID: f.parentID, Operator: " 张三 ", Location: " 实验室A ",
365					At:     f.in.At.In(time.FixedZone("UTC+8", 8*3600)),
366					Reason: " 实验结束按规程销毁 ",
367				})
368				if err != nil {
369					t.Fatalf("成功后相同信息的重复提交应幂等返回: %v", err)
370				}
371				if !reflect.DeepEqual(again, destroyed) {
372					t.Fatalf("重复提交应返回与成功重试相同的结果:\n first=%+v\n again=%+v",
373						destroyed, again)
374				}
375				parentAgain, _ := f.s.GetSample(f.parentID)
376				if len(parentAgain.History) != len(destroyed.History) {
377					t.Fatalf("重复提交不得再次追加历史: first=%d again=%d",
378						len(destroyed.History), len(parentAgain.History))
379				}
380	
381				// 成功的重试已正常落盘：重开后销毁信息、数量、子样列表与各自
382				// 保管历史都保持，子样仍独立持有 3.250 毫升。
383				s2, err := Open(f.path)
384				if err != nil {
385					t.Fatalf("reopen after retry: %v", err)
386				}
387				reopened, err := s2.GetSample(f.parentID)
388				if err != nil {
389					t.Fatal(err)
390				}
391				if reopened.InitialQty != "10.000" || reopened.Remaining != "0.000" ||
392					reopened.Destruction == nil || reopened.Destruction.Qty != "6.750" ||
393					len(reopened.Children) != 1 || reopened.Children[0] != f.childID ||
394					len(reopened.History) != len(destroyed.History) ||
395					reopened.History[len(reopened.History)-1].Kind != "destroy" {
396					t.Fatalf("重开后原样销毁状态错误: %+v", reopened)
397				}
398				reopenedChild, err := s2.GetSample(f.childID)
399				if err != nil {
400					t.Fatal(err)
401				}
402				if !reflect.DeepEqual(reopenedChild, f.childBefore) {
403					t.Fatalf("重开后原有子样应保持独立状态:\n before=%+v\n after =%+v",
404						f.childBefore, reopenedChild)
405				}
406				// 重开后相同销毁请求仍幂等，改变任一项仍按冲突拒绝。
407				if _, err := s2.Destroy(f.in); err != nil {
408					t.Fatalf("重开后相同销毁请求应幂等返回: %v", err)
409				}
410				mutated := f.in
411				mutated.Reason = "别的原因"
412				if _, err := s2.Destroy(mutated); !errors.Is(err, ErrConflict) {
413					t.Fatalf("重开后销毁幂等判断应继续生效, got %v", err)
414				}
415			})
416		}
417	}
418

