1	package custody
2	
3	import (
4		"errors"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9		"time"
10	)
11	
12	// writeRawLedger 把原始 JSON 写入临时目录并返回路径，用于构造
13	// 无法通过公开操作产生的损坏数据文件。
14	func writeRawLedger(t *testing.T, content string) string {
15		t.Helper()
16		path := filepath.Join(t.TempDir(), "data.json")
17		if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
18			t.Fatalf("写入测试数据文件: %v", err)
19		}
20		return path
21	}
22	
23	// mustRejectOpen 断言打开损坏文件失败：返回 nil Store、错误可用
24	// errors.Is 判定为 ErrInvalid、错误文字提及全部给定编号，且原文件
25	// 内容不被改写。
26	func mustRejectOpen(t *testing.T, path string, mentions ...string) {
27		t.Helper()
28		before, err := os.ReadFile(path)
29		if err != nil {
30			t.Fatalf("读取测试数据文件: %v", err)
31		}
32		s, err := Open(path)
33		if err == nil {
34			t.Fatalf("损坏的数据文件不应打开成功")
35		}
36		if s != nil {
37			t.Fatalf("打开失败时不应返回可用的 Store")
38		}
39		if !errors.Is(err, ErrInvalid) {
40			t.Fatalf("错误应可用 errors.Is 判定为 ErrInvalid, got %v", err)
41		}
42		for _, m := range mentions {
43			if !strings.Contains(err.Error(), m) {
44				t.Fatalf("错误文字应提及 %q: %v", m, err)
45			}
46		}
47		after, err := os.ReadFile(path)
48		if err != nil {
49			t.Fatalf("重新读取测试数据文件: %v", err)
50		}
51		if string(before) != string(after) {
52			t.Fatalf("打开失败不得改写原文件")
53		}
54	}
55	
56	// 一份合法的最简样品记录 JSON 片段（无待确认交接）。
57	const rawSampleS1 = `"S1": {"id":"S1","initial":1000,"remaining":1000,"holder":"张三","location":"A","children":[],"history":[{"kind":"register","time":"2026-10-02T09:00:00Z","holder":"张三","location":"A"}]}`
58	
59	func TestOpenRejectsDanglingPendingID(t *testing.T) {
60		path := writeRawLedger(t, `{
61			"version": 1,
62			"samples": {"S1": {"id":"S1","initial":1000,"remaining":1000,"holder":"张三","location":"A","children":[],"history":[],"pendingId":"T-ghost"}},
63			"transfers": {}
64		}`)
65		mustRejectOpen(t, path, "S1", "T-ghost")
66	}
67	
68	func TestOpenRejectsPendingIDToNullTransfer(t *testing.T) {
69		path := writeRawLedger(t, `{
70			"version": 1,
71			"samples": {"S1": {"id":"S1","initial":1000,"remaining":1000,"holder":"张三","location":"A","children":[],"history":[],"pendingId":"T1"}},
72			"transfers": {"T1": null}
73		}`)
74		mustRejectOpen(t, path, "S1", "T1")
75	}
76	
77	func TestOpenRejectsPendingIDToConfirmedTransfer(t *testing.T) {
78		path := writeRawLedger(t, `{
79			"version": 1,
80			"samples": {"S1": {"id":"S1","initial":1000,"remaining":1000,"holder":"张三","location":"A","children":[],"history":[],"pendingId":"T1"}},
81			"transfers": {"T1": {"id":"T1","sampleId":"S1","fromHolder":"张三","fromLocation":"A","toHolder":"李四","toLocation":"B","qty":1000,"handedOverAt":"2026-10-02T09:00:00Z","confirmed":true,"receivedAt":"2026-10-02T10:00:00Z","confirmedBy":"李四"}}
82		}`)
83		mustRejectOpen(t, path, "S1", "T1")
84	}
85	
86	func TestOpenRejectsPendingIDToOtherSamplesTransfer(t *testing.T) {
87		path := writeRawLedger(t, `{
